WITH flattened AS (SELECT id, service, level, latency_ms, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) e AS attr_key, attr_value) SELECT id, level, latency_ms, attr_key, attr_value, CASE WHEN level RLIKE '^(WARN|INFO)$' THEN 'OTHER_ZONE' WHEN level RLIKE '^(ERROR|DEBUG)$' THEN 'PRIORITY' ELSE 'EXTENDED' END AS level_zone FROM flattened ORDER BY id DESC
